export function isAllowedTool(toolName: string, allowedTools?: string[]): boolean {
  return !allowedTools || allowedTools.includes(toolName);
}

export function formatPromptValue(value: unknown): string {
  if (value === null) {
    return 'null';
  }
  if (Array.isArray(value)) {
    return `[${value.map(formatPromptValue).join(',')}]`;
  }
  if (typeof value === 'object') {
    const record = value as Record<string, unknown>;
    return `{${Object.keys(record)
      .sort()
      .map((key) => `${key}:${formatPromptValue(record[key])}`)
      .join(',')}}`;
  }
  if (typeof value === 'string') {
    return `"${value.replaceAll('\\', '\\\\').replaceAll('"', '\\"')}"`;
  }
  if (typeof value === 'number' || typeof value === 'boolean' || typeof value === 'bigint') {
    return String(value);
  }
  if (typeof value === 'undefined') {
    return 'undefined';
  }
  return Object.prototype.toString.call(value);
}

export function parseToolArgs(rawArgs: string | undefined, toolName: string): { args: Record<string, unknown>; parseError: boolean } {
  try {
    return { args: JSON.parse(rawArgs || '{}') as Record<string, unknown>, parseError: false };
  } catch {
    return { args: {}, parseError: true };
  }
}

import { StructuredLogger } from '../logging/structured-logger';
import { AbiBuilderService } from './abi/abi-builder.service';
import { validateAbiPayload } from './abi/abi-validator';

type UnknownRecord = Record<string, unknown>;

export async function buildUnifiedAgentCognitiveState(params: {
  abiBuilder?: AbiBuilderService;
  currentInput: UnknownRecord;
  logger: StructuredLogger;
}): Promise<UnknownRecord> {
  const { abiBuilder, currentInput, logger } = params;
  const channel = String(currentInput.channel ?? 'whatsapp');

  let cognitiveState: UnknownRecord = {
    abiStatus: abiBuilder ? 'unavailable_or_invalid' : 'builder_not_injected',
    audience: 'public',
    perceptionSnapshot: { channel },
  };

  if (abiBuilder) {
    const abiResult = await abiBuilder.build({
      audience: 'public',
      currentInput,
      perceptionSnapshot: {
        channel,
      },
    });

    if (abiResult.status !== 'ok') {
      logger.warn(
        `ABI build failed: ${abiResult.reason}, using structured unified agent fallback`,
      );
    } else {
      const validation = validateAbiPayload(abiResult.abi);

      if (validation.status === 'FAIL') {
        logger.warn(
          `ABI validation failed: ${JSON.stringify(validation.issues)}, using structured unified agent fallback`,
        );
      } else {
        cognitiveState = abiResult.abi as unknown as UnknownRecord;
      }
    }
  }

  return cognitiveState;
}

import type { AgentRuntimeContextService } from './agent-runtime';

export async function buildAgentRuntimeContext(params: {
  agentRuntime?: AgentRuntimeContextService;
  workspaceId: string;
  channel: string;
  message: string;
  contactId?: string;
  allowedTools?: string[];
}): Promise<{ systemPromptBlock: string }> {
  const { agentRuntime } = params;
  if (!agentRuntime) {
    return { systemPromptBlock: '' };
  }
  return agentRuntime.buildContext({
    workspaceId: params.workspaceId,
    channel: params.channel,
    message: params.message,
    ...(params.contactId !== undefined ? { contactId: params.contactId } : {}),
    ...(params.allowedTools !== undefined ? { allowedTools: params.allowedTools } : {}),
  });
}

