import type { Prisma } from '@prisma/client';
import type { ToolArgs } from './unified-agent.types';

type UnknownRecord = Record<string, unknown>;

export interface ExecuteToolActionDeps {
  actions: UnifiedAgentActionsService;
  riskGate?: RiskGateService;
  prisma: PrismaService;
  auditService: AuditService;
  agentRuntime?: AgentRuntimeContextService;
  openai: OpenAI | null;
  primaryBrainModel: string;
  fallbackBrainModel: string;
}

export function num(v: unknown, fb = 0): number {
  const n = Number(v);
  return Number.isFinite(n) ? Math.round(n) : fb;
}

export function actionSucceeded(result: unknown): boolean {
  if (!result || typeof result !== 'object' || Array.isArray(result)) {
    return false;
  }
  const record = result as Record<string, unknown>;
  return record.success === true || record.ok === true || record.executed === true;
}

export function buildAgentToolEnvelope(
  agentRuntime: AgentRuntimeContextService | undefined,
  params: { workspaceId: string; toolName: string },
): { id: string; toolName: string; allowed: boolean } {
  return (
    agentRuntime?.buildToolEnvelope(params) ?? {
      id: 'agent-runtime-unavailable',
      toolName: params.toolName,
      allowed: true,
    }
  );
}

export async function executeToolAction(
  workspaceId: string,
  contactId: string,
  phone: string,
  tool: string,
  args: ToolArgs,
  context: UnknownRecord | undefined,
  deps: ExecuteToolActionDeps,
  logger: StructuredLogger,
): Promise<unknown> {
  const { actions, riskGate, prisma, auditService, agentRuntime } = deps;

  logger.log(`Executing tool: ${tool}`, { args });
  const envelope = buildAgentToolEnvelope(agentRuntime, {
    workspaceId,
    toolName: tool,
  });

  switch (tool) {
    case 'send_message':
      return actions.actionSendMessage(workspaceId, phone, args, context);
    case 'send_product_info':
      return actions.actionSendProductInfo(workspaceId, phone, args, context);
    case 'create_payment_link': {
      const paymentAmount = num(args.amount);
      if (riskGate && paymentAmount > 0) {
        const gateDecision = riskGate.gatePaymentAction({
          amountCents: paymentAmount,
          reversible: true,
          target: 'lead',
        });
        if (gateDecision.verdict === 'block') {
          logger.error(
            `R4 BLOCKED: create_payment_link — ${gateDecision.reason}`,
          );
          return {
            success: false,
            blocked: true,
            riskClass: gateDecision.classification.class,
            error: gateDecision.reason,
          };
        }
        if (gateDecision.verdict === 'warn') {
          logger.warn(
            `Risk gate: payment ${gateDecision.classification.class} — ${gateDecision.reason}`,
          );
        }
      }
      const result = await actions.actionCreatePaymentLink(
        workspaceId,
        phone,
        args,
        context,
      );
      try {
        await prisma.$transaction(
          async (tx) => {
            await auditService.logWithTx(tx, {
              workspaceId,
              action: 'AGENT_DISPATCHED_PAYMENT_LINK',
              resource: 'UnifiedAgent',
              resourceId: contactId,
              details: { tool, phone },
            });
          },
          { isolationLevel: 'ReadCommitted' as Prisma.TransactionIsolationLevel },
        );
      } catch (auditError: unknown) {
        const auditMsg =
          auditError instanceof Error
            ? auditError.message
            : typeof auditError === 'string'
              ? auditError
              : 'unknown';
        logger.warn(`Audit dispatch log failed: ${auditMsg}`);
      }
      return result;
    }
    case 'update_lead_status':
      return actions.actionUpdateLeadStatus(workspaceId, contactId, args);
    case 'add_tag':
      return actions.actionAddTag(workspaceId, contactId, args);
    case 'schedule_followup':
      return actions.actionScheduleFollowup(workspaceId, contactId, phone, args, context);
    case 'transfer_to_human':
      return actions.actionTransferToHuman(workspaceId, contactId, args, context);
    case 'search_knowledge_base':
      return actions.actionSearchKnowledgeBase(workspaceId, args);
    case 'trigger_flow':
      return actions.actionTriggerFlow(workspaceId, phone, args);
    case 'log_event':
      return actions.actionLogEvent(workspaceId, contactId, args);
    case 'send_media':
      return actions.actionSendMedia(workspaceId, phone, args, context);
    case 'send_document':
      return actions.actionSendDocument(workspaceId, phone, args, context);
    case 'send_voice_note':
      return actions.actionSendVoiceNote(workspaceId, phone, args, context);
    case 'send_audio':
      return actions.actionSendAudio(workspaceId, phone, args, context);
    case 'transcribe_audio':
      return actions.actionTranscribeAudio(workspaceId, args);
    case 'create_product':
      return actions.actionCreateProduct(workspaceId, args);
    case 'update_product':
      return actions.actionUpdateProduct(workspaceId, args);
    case 'get_product_plans':
      return actions.getProductPlans(actions.str(args.productId));
    case 'get_product_ai_config':
      return actions.getProductAIConfig(actions.str(args.productId));
    case 'get_product_reviews':
      return actions.getProductReviews(actions.str(args.productId));
    case 'get_product_urls':
      return actions.getProductUrls(actions.str(args.productId));
    case 'validate_coupon':
      return actions.validateCoupon(
        actions.str(args.productId),
        actions.str(args.code),
      );
    case 'create_flow':
      return actions.actionCreateFlow(workspaceId, args);
    case 'update_workspace_settings':
      return actions.actionUpdateWorkspaceSettings(workspaceId, args);
    case 'create_broadcast':
      return actions.actionCreateBroadcast(workspaceId, args, context);
    case 'get_analytics':
      return actions.actionGetAnalytics(workspaceId, args);
    case 'configure_ai_persona':
      return actions.actionConfigureAIPersona(workspaceId, args);
    case 'toggle_autopilot':
      return actions.actionToggleAutopilot(workspaceId, args);
    case 'create_flow_from_description':
      return actions.actionCreateFlowFromDescription(
        workspaceId,
        args,
        deps.openai,
        deps.primaryBrainModel,
        deps.fallbackBrainModel,
      );
    case 'connect_whatsapp':
      return actions.actionConnectWhatsApp(workspaceId, args);
    case 'import_contacts':
      return actions.actionImportContacts(workspaceId, args);
    case 'generate_sales_funnel':
      return actions.actionGenerateSalesFunnel(workspaceId, args);
    case 'schedule_campaign':
      return actions.actionScheduleCampaign(workspaceId, args);
    case 'get_workspace_status':
      return actions.actionGetWorkspaceStatus(workspaceId, args);
    case 'update_billing_info':
      return actions.actionUpdateBillingInfo(workspaceId, args);
    case 'get_billing_status':
      return actions.actionGetBillingStatus(workspaceId);
    case 'change_plan':
      return actions.actionChangePlan(workspaceId, args);
    case 'apply_discount':
      if (riskGate) {
        const gateDecision = riskGate.gateDiscountOffer({
          amountCents: 0,
          reversible: true,
          target: 'lead',
        });
        if (gateDecision.verdict === 'block') {
          logger.error(
            `R4 BLOCKED: apply_discount — ${gateDecision.reason}`,
          );
          return {
            success: false,
            blocked: true,
            riskClass: gateDecision.classification.class,
            error: gateDecision.reason,
          };
        }
        if (gateDecision.verdict === 'warn') {
          logger.warn(
            `Risk gate: discount ${gateDecision.classification.class} — ${gateDecision.reason}`,
          );
        }
      }
      return actions.actionApplyDiscount(workspaceId, contactId, phone, args, context);
    case 'handle_objection':
      return actions.actionHandleObjection(workspaceId, contactId, phone, args, context);
    case 'qualify_lead':
      return actions.actionQualifyLead(workspaceId, contactId, phone, args, context);
    case 'schedule_meeting':
      return actions.actionScheduleMeeting(workspaceId, contactId, phone, args, context);
    case 'anti_churn_action':
      return actions.actionAntiChurn(workspaceId, contactId, phone, args, context);
    case 'reactivate_ghost':
      return actions.actionReactivateGhost(workspaceId, contactId, phone, args, context);
    default:
      logger.warn(`Unknown tool: ${tool}`);
      return { success: false, error: 'Unknown tool', policyEnvelope: envelope };
  }
}

import type { ActionEntry } from './unified-agent.types';

type UnknownRecord = Record<string, unknown>;

export async function processIncomingUnifiedAgentMessage(params: {
  workspaceId: string;
  phone: string;
  message: string;
  contactId?: string;
  channel?: string;
  context?: UnknownRecord;
  executeTools?: boolean;
  processMessage: (msg: {
    workspaceId: string;
    contactId: string;
    phone: string;
    message: string;
    context?: UnknownRecord;
    allowedTools?: string[];
    predecidedActions?: import('./unified-agent.types').PredecidedAction[];
  }) => Promise<{ actions: ActionEntry[]; response?: string; intent: string; confidence: number }>;
}): Promise<{
  reply?: string;
  response?: string;
  actions: ActionEntry[];
  intent: string;
  confidence: number;
}> {
  const result = await params.processMessage({
    workspaceId: params.workspaceId,
    contactId: params.contactId || '',
    phone: params.phone,
    message: params.message,
    context: {
      channel: params.channel || 'whatsapp',
      executeTools: params.executeTools !== false,
      ...(params.context || {}),
    },
  });

  return {
    actions: result.actions,
    intent: result.intent,
    confidence: result.confidence,
    ...(result.response !== undefined
      ? { reply: result.response, response: result.response }
      : {}),
  };
}

import type OpenAI from 'openai';
import type { StructuredLogger } from '../logging/structured-logger';
import type { UnifiedAgentActionsService } from './unified-agent-actions.service';
import type { ActionEntry } from './unified-agent.types';
import { forEachSequential } from '../common/async-sequence';
import { isAllowedTool, parseToolArgs } from './unified-agent-tool-parser.helpers';
import type { executeToolAction } from './unified-agent-tool-router.helpers';

type UnknownRecord = Record<string, unknown>;
type ToolCallExecutor = typeof executeToolAction;

export async function processUnifiedAgentToolCalls(params: {
  toolCalls: OpenAI.Chat.ChatCompletionMessage['tool_calls'];
  allowedTools?: string[];
  workspaceId: string;
  contactId: string;
  phone: string;
  context?: UnknownRecord;
  actions: UnifiedAgentActionsService;
  executeToolAction: ToolCallExecutor;
  toolActionDeps: Parameters<ToolCallExecutor>[6];
  logger: StructuredLogger;
}): Promise<ActionEntry[]> {
  const {
    toolCalls,
    allowedTools,
    workspaceId,
    contactId,
    phone,
    context,
    actions,
    executeToolAction: execTool,
    toolActionDeps,
    logger,
  } = params;

  const actionsList: ActionEntry[] = [];

  if (!toolCalls || toolCalls.length === 0) {
    return actionsList;
  }

  await forEachSequential(toolCalls, async (toolCall) => {
    if (toolCall.type !== 'function') {
      return;
    }
    const toolName = toolCall.function.name;
    if (!isAllowedTool(toolName, allowedTools)) {
      logger.warn(
        `Blocked disallowed agent tool call: workspaceId=${workspaceId} tool=${toolName}`,
      );
      const blockedResult = { blocked: true, reason: 'capability_not_allowed' };
      actionsList.push({ tool: toolName, args: {}, result: blockedResult });
      await actions.logAutopilotEvent(workspaceId, contactId, toolName, {}, blockedResult);
      return;
    }
    const { args: toolArgs, parseError } = parseToolArgs(
      toolCall.function.arguments,
      toolName,
    );
    if (parseError) {
      logger.warn(`Failed to parse tool args for ${toolName}`);
    }
    const result = await execTool(
      workspaceId,
      contactId,
      phone,
      toolName,
      toolArgs,
      context,
      toolActionDeps,
      logger,
    );
    actionsList.push({ tool: toolName, args: toolArgs, result });
    await actions.logAutopilotEvent(workspaceId, contactId, toolName, toolArgs, result);
  });

  return actionsList;
}

import OpenAI from 'openai';
import type { StructuredLogger } from '../logging/structured-logger';
import type { UnifiedAgentResponseService } from './unified-agent-response.service';
import type { UnifiedAgentActionsService } from './unified-agent-actions.service';
import type { ActionEntry, PredecidedAction, ToolArgs } from './unified-agent.types';
import { buildPredecidedActionDraft, executePredecidedAgentActions } from './unified-agent-predecided-actions.part';
import { actionSucceeded } from './unified-agent-tool-router.helpers';
import type { executeToolAction } from './unified-agent-tool-router.helpers';
import type { recordAgentRuntimeTurn } from './unified-agent-runtime.helpers';

type UnknownRecord = Record<string, unknown>;
type ToolCallExecutor = typeof executeToolAction;
type RecordTurnFn = typeof recordAgentRuntimeTurn;

export async function processUnifiedAgentPredecidedActions(params: {
  predecidedActions: PredecidedAction[];
  allowedTools?: string[];
  contactId: string;
  context?: UnknownRecord;
  phone: string;
  workspaceId: string;
  message: string;
  channel: string;
  conversationHistoryLength: number;
  actions: UnifiedAgentActionsService;
  response: UnifiedAgentResponseService;
  openai: OpenAI | null;
  writerModel: string;
  fallbackWriterModel: string;
  executeToolAction: ToolCallExecutor;
  toolActionDeps: Parameters<ToolCallExecutor>[6];
  recordAgentRuntimeTurn: RecordTurnFn;
  recordAgentRuntimeTurnDeps: Parameters<RecordTurnFn>[0];
  logger: StructuredLogger;
}): Promise<{
  actions: ActionEntry[];
  response?: string;
  intent: string;
  confidence: number;
}> {
  const {
    allowedTools,
    contactId,
    context,
    phone,
    workspaceId,
    message,
    channel,
    conversationHistoryLength,
    actions,
    response,
    openai,
    writerModel,
    fallbackWriterModel,
    executeToolAction: execTool,
    toolActionDeps,
    recordAgentRuntimeTurn: recordTurn,
    recordAgentRuntimeTurnDeps,
    logger,
  } = params;

  const actionsList = await executePredecidedAgentActions({
    ...(allowedTools !== undefined ? { allowedTools } : {}),
    contactId,
    ...(context !== undefined ? { context } : {}),
    executeTool: (
      wsId: string,
      ctId: string,
      ph: string,
      tool: string,
      args: ToolArgs,
      ctx?: UnknownRecord,
    ) => execTool(wsId, ctId, ph, tool, args, ctx, toolActionDeps, logger),
    logAutopilotEvent: actions.logAutopilotEvent.bind(actions),
    phone,
    predecidedActions: params.predecidedActions,
    workspaceId,
  });

  const intent = response.extractIntent(actionsList, message);
  const draftedReply = await response.composeWriterReply(
    openai,
    writerModel,
    fallbackWriterModel,
    {
      workspaceId,
      customerMessage: message,
      assistantDraft: buildPredecidedActionDraft(actionsList),
      actions: actionsList,
      historyTurns: conversationHistoryLength,
    },
  );

  await recordTurn({
    ...recordAgentRuntimeTurnDeps,
    channel,
    userMessage: message,
    ...(draftedReply !== undefined ? { assistantMessage: draftedReply } : {}),
    contactId,
    intent,
    confidence: actionsList.length > 0 ? 0.85 : 0.55,
    actions: actionsList.map((action) => ({
      toolName: action.tool,
      success: actionSucceeded(action.result),
      result: action.result,
    })),
  });

  return {
    actions: actionsList,
    ...(draftedReply !== undefined ? { response: draftedReply } : {}),
    intent,
    confidence: actionsList.length > 0 ? 0.85 : 0.55,
  };
}

import { Injectable, Optional } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { StructuredLogger } from '../logging/structured-logger';
import OpenAI from 'openai';
import type { ChatCompletionMessageParam } from 'openai/resources/chat';
import { PlanLimitsService } from '../billing/plan-limits.service';
import { AuditService } from '../audit/audit.service';
import { createTextLlmClient } from '../lib/llm-provider';
import { resolveBackendOpenAIModel } from '../lib/openai-models';
import { PrismaService } from '../prisma/prisma.service';
import { chatCompletionWithFallback } from './openai-wrapper';
import { UnifiedAgentContextService } from './unified-agent-context.service';
import { UnifiedAgentResponseService } from './unified-agent-response.service';
import { UnifiedAgentActionsService } from './unified-agent-actions.service';
import { AgentRuntimeContextService } from './agent-runtime';
import { AbiBuilderService } from './abi/abi-builder.service';
import { RiskGateService } from './risk-class/risk-gate.service';
export type { ToolArgs, ActionEntry } from './unified-agent.types';
import type { ToolArgs, ActionEntry, PredecidedAction } from './unified-agent.types';
import { formatPromptValue } from './unified-agent-tool-parser.helpers';
import { buildUnifiedAgentCognitiveState } from './unified-agent-cognitive-state.helpers';
import { buildAgentRuntimeContext, recordAgentRuntimeTurn } from './unified-agent-runtime.helpers';
import {
  num,
  actionSucceeded,
  executeToolAction,
  type ExecuteToolActionDeps,
} from './unified-agent-tool-router.helpers';
import { processIncomingUnifiedAgentMessage } from './unified-agent-incoming-message.helpers';
import { processUnifiedAgentToolCalls } from './unified-agent-tool-call-processing.helpers';
import { processUnifiedAgentPredecidedActions } from './unified-agent-predecided-processing.helpers';

type UnknownRecord = Record<string, unknown>;

const UNIFIED_AGENT_PROVIDER_CONFIG_REQUIRED =
  'Primary LLM configuration is required for unified agent generation';

/**
 * KLOEL Unified Agent Service — orchestrator.
 *
 * This service coordinates context loading, LLM calls, tool dispatch, and
 * response composition. All heavy logic lives in the sub-services injected
 * here. The constructor, processMessage, and executeToolAction router are the
 * only concerns of this file.
 */
/** Idempotency: enforced at HTTP layer via @Idempotent() guard + Stripe idempotencyKey. */
@Injectable()
export class UnifiedAgentService {
  private readonly logger = StructuredLogger.from(UnifiedAgentService.name);
  private readonly openai: OpenAI | null;
  private readonly primaryBrainModel: string;
  private readonly fallbackBrainModel: string;
  private readonly writerModel: string;
  private readonly fallbackWriterModel: string;

  constructor(
    private readonly prisma: PrismaService,
    private readonly config: ConfigService,
    private readonly planLimits: PlanLimitsService,
    private readonly auditService: AuditService,
    private readonly ctx: UnifiedAgentContextService,
    private readonly response: UnifiedAgentResponseService,
    private readonly actions: UnifiedAgentActionsService,
    @Optional() private readonly agentRuntime?: AgentRuntimeContextService,
    @Optional() private readonly abiBuilder?: AbiBuilderService,
    @Optional() private readonly riskGate?: RiskGateService,
  ) {
    this.openai = createTextLlmClient(this.config);
    this.primaryBrainModel = resolveBackendOpenAIModel('brain', this.config);
    this.fallbackBrainModel = resolveBackendOpenAIModel('brain_fallback', this.config);
    this.writerModel = resolveBackendOpenAIModel('writer', this.config);
    this.fallbackWriterModel = resolveBackendOpenAIModel('writer_fallback', this.config);
  }

  async processIncomingMessage(params: {
    workspaceId: string;
    phone: string;
    message: string;
    contactId?: string;
    channel?: string;
    context?: UnknownRecord;
    executeTools?: boolean;
  }): Promise<{
    reply?: string;
    response?: string;
    actions: ActionEntry[];
    intent: string;
    confidence: number;
  }> {
    return processIncomingUnifiedAgentMessage({
      ...params,
      processMessage: this.processMessage.bind(this),
    });
  }

  async processMessage(params: {
    allowedTools?: string[];
    predecidedActions?: PredecidedAction[];
    workspaceId: string;
    contactId: string;
    phone: string;
    message: string;
    context?: UnknownRecord;
  }): Promise<{
    actions: ActionEntry[];
    response?: string;
    intent: string;
    confidence: number;
  }> {
    const { workspaceId, contactId, phone, message, context } = params;

    const predecidedActions = params.predecidedActions ?? [];

    if (!this.openai && predecidedActions.length === 0) {
      this.logger.warn('OpenAI not configured');
      return this.response.buildFallbackResult(message);
    }

    const channel = this.ctx.readText(context?.channel, 'whatsapp');

    // 1. Load workspace / contact / history / products in parallel
    const [workspace, contact, conversationHistory, products] = await Promise.all([
      this.ctx.getWorkspaceContext(workspaceId),
      this.ctx.getContactContext(workspaceId, contactId, phone),
      this.ctx.getConversationHistory(workspaceId, contactId, 0, phone),
      this.ctx.getProducts(workspaceId),
    ]);

    // 1b. Load AI config per product (commercial brain)
    const productIds = products
      .map((product: UnknownRecord) => {
        const productValue = this.ctx.readRecord(product.value);
        return this.ctx.readOptionalText(productValue.id) || this.ctx.readOptionalText(product.id);
      })
      .filter((productId): productId is string => Boolean(productId));
    let aiConfigs: UnknownRecord[] = [];
    if (productIds.length > 0) {
      try {
        aiConfigs = await this.prisma.productAIConfig.findMany({
          take: 50,
          where: { productId: { in: productIds } },
          select: {
            id: true,
            productId: true,
            tone: true,
            persistenceLevel: true,
            messageLimit: true,
            customerProfile: true,
            positioning: true,
            objections: true,
            salesArguments: true,
          },
        });
      } catch {
        /* ProductAIConfig may not exist yet */
      }
    }

    const compressedContext = await this.ctx.buildAndPersistCompressedContext(
      workspaceId,
      contactId,
      phone,
      contact,
    );
    const tacticalHint = this.ctx.buildLeadTacticalHint({
      leadName: this.ctx.isRecord(contact) ? this.ctx.readText(contact.name).trim() : '',
      currentMessage: message,
      conversationHistory,
    });

    // 2. Build system prompt and style instruction
    const agentRuntimeContextResult = await buildAgentRuntimeContext({
      agentRuntime: this.agentRuntime,
      workspaceId,
      channel,
      message,
      contactId,
      ...(params.allowedTools !== undefined ? { allowedTools: params.allowedTools } : {}),
    });
    const systemPrompt = [
      this.ctx.buildSystemPrompt(workspace, products, aiConfigs),
      agentRuntimeContextResult.systemPromptBlock,
    ].join('\n\n');
    const stylePolicy = this.response.buildReplyStyleInstruction(
      message,
      conversationHistory.length,
    );
    const contactData: Record<string, unknown> = this.ctx.isRecord(contact) ? contact : {};
    const contactName = this.ctx.readText(contactData.name).trim() || phone;
    const contactSentiment = this.ctx.readText(contactData.sentiment).trim() || 'NEUTRAL';
    const leadScore = this.ctx.readText(contactData.leadScore, '0');
    const tagNames = this.ctx.readTagList(contactData.tags);

    // 3. Build messages array
    const additionalContext = context ? formatPromptValue(context) : '';
    const currentInput: UnknownRecord = {
      raw: message,
      channel,
      arrivalTimestamp: new Date().toISOString(),
    };

    const cognitiveState = await buildUnifiedAgentCognitiveState({
      abiBuilder: this.abiBuilder,
      currentInput,
      logger: this.logger,
    });

    const messages: ChatCompletionMessageParam[] = [
      ...conversationHistory,
      {
        role: 'user',
        content: JSON.stringify({
          cognitiveState,
          runtimeContext: {
            workspaceProductContext: systemPrompt,
            compressedMemory: compressedContext || null,
            additionalContext,
            tacticalHint:
              tacticalHint || 'responder com clareza, valor concreto e próximo passo.',
            responsePolicy: stylePolicy,
          },
          contact: {
            name: contactName,
            sentiment: contactSentiment,
            leadScore,
            tags: tagNames,
          },
          currentInput,
        }),
      },
    ];

    const toolActionDeps: ExecuteToolActionDeps = {
      actions: this.actions,
      riskGate: this.riskGate,
      prisma: this.prisma,
      auditService: this.auditService,
      agentRuntime: this.agentRuntime,
      openai: this.openai,
      primaryBrainModel: this.primaryBrainModel,
      fallbackBrainModel: this.fallbackBrainModel,
    };

    const recordTurnParams = {
      agentRuntime: this.agentRuntime,
      workspaceId,
      channel,
      userMessage: message,
      contactId,
    };

    if (predecidedActions.length > 0) {
      return processUnifiedAgentPredecidedActions({
        predecidedActions,
        ...(params.allowedTools !== undefined ? { allowedTools: params.allowedTools } : {}),
        contactId,
        ...(context !== undefined ? { context } : {}),
        phone,
        workspaceId,
        message,
        channel,
        conversationHistoryLength: conversationHistory.length,
        actions: this.actions,
        response: this.response,
        openai: this.openai,
        writerModel: this.writerModel,
        fallbackWriterModel: this.fallbackWriterModel,
        executeToolAction,
        toolActionDeps,
        recordAgentRuntimeTurn,
        recordAgentRuntimeTurnDeps: recordTurnParams,
        logger: this.logger,
      });
    }

    // 4. Ask the LLM to verbalize only; code-native actions enter via predecidedActions.
    let llmResponse: OpenAI.Chat.ChatCompletion;
    try {
      await this.planLimits.ensureTokenBudget(params.workspaceId);
      const openai = this.openai;
      if (!openai) {
        const error = new Error();
        error.message = UNIFIED_AGENT_PROVIDER_CONFIG_REQUIRED;
        throw error;
      }
      llmResponse = await chatCompletionWithFallback(
        openai,
        {
          model: this.primaryBrainModel,
          messages,
          temperature: 0.82,
          top_p: 0.9,
        },
        this.fallbackBrainModel,
      );
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : typeof err === 'string' ? err : 'unknown';
      this.logger.error(`OpenAI agent processing failed, using fallback: ${msg}`);
      return this.response.buildFallbackResult(message);
    }
    if (!llmResponse) {
      return this.response.buildFallbackResult(message);
    }
    const firstChoice = llmResponse.choices[0];
    if (!firstChoice) {
      return this.response.buildFallbackResult(message);
    }
    await this.planLimits
      .trackAiUsage(params.workspaceId, llmResponse.usage?.total_tokens ?? 500)
      .catch(() => {});

    const assistantMessage = firstChoice.message;

    // 5. Process tool calls
    const executeToolsContext = context?.executeTools !== false;
    let actionsList: ActionEntry[];
    if (
      executeToolsContext &&
      assistantMessage.tool_calls &&
      assistantMessage.tool_calls.length > 0
    ) {
      actionsList = await processUnifiedAgentToolCalls({
        toolCalls: assistantMessage.tool_calls,
        allowedTools: params.allowedTools,
        workspaceId,
        contactId,
        phone,
        context,
        actions: this.actions,
        executeToolAction,
        toolActionDeps,
        logger: this.logger,
      });
    } else {
      actionsList = [];
    }

    // 6. Extract intent, confidence, and compose final reply
    const intent = this.response.extractIntent(actionsList, message);
    const confidence = this.response.calculateConfidence(actionsList, llmResponse);
    const draftedReply = await this.response.composeWriterReply(
      this.openai,
      this.writerModel,
      this.fallbackWriterModel,
      {
        workspaceId,
        customerMessage: message,
        assistantDraft: assistantMessage.content,
        actions: actionsList,
        historyTurns: conversationHistory.length,
      },
    );

    await recordAgentRuntimeTurn({
      ...recordTurnParams,
      ...(draftedReply !== undefined ? { assistantMessage: draftedReply } : {}),
      intent,
      confidence,
      actions: actionsList.map((action) => ({
        toolName: action.tool,
        success: actionSucceeded(action.result),
        result: action.result,
      })),
    });

    return {
      actions: actionsList,
      ...(draftedReply !== undefined ? { response: draftedReply } : {}),
      intent,
      confidence,
    };
  }

  /**
   * Public API: execute a single named tool directly.
   */
  async executeTool(
    tool: string,
    args: ToolArgs,
    ctx: { workspaceId: string; contactId?: string; phone?: string },
  ): Promise<unknown> {
    return executeToolAction(
      ctx.workspaceId,
      ctx.contactId || '',
      ctx.phone || '',
      tool,
      args,
      undefined,
      {
        actions: this.actions,
        riskGate: this.riskGate,
        prisma: this.prisma,
        auditService: this.auditService,
        agentRuntime: this.agentRuntime,
        openai: this.openai,
        primaryBrainModel: this.primaryBrainModel,
        fallbackBrainModel: this.fallbackBrainModel,
      },
      this.logger,
    );
  }

  /** Build quoted reply plan (delegates to response service). */
  async buildQuotedReplyPlan(params: {
    workspaceId: string;
    contactId?: string;
    phone: string;
    draftReply: string;
    customerMessages: Array<{ content: string; quotedMessageId: string }>;
  }): Promise<Array<{ quotedMessageId: string; text: string }>> {
    return this.response.buildQuotedReplyPlan(
      this.openai,
      this.writerModel,
      this.fallbackWriterModel,
      this.planLimits,
      params,
    );
  }
}

import OpenAI from 'openai';
import type { StructuredLogger } from '../logging/structured-logger';
import type { UnifiedAgentResponseService } from './unified-agent-response.service';
import type { UnifiedAgentActionsService } from './unified-agent-actions.service';
import type { AgentRuntimeContextService } from './agent-runtime';
import type { ActionEntry, PredecidedAction, ToolArgs } from './unified-agent.types';
import { buildPredecidedActionDraft, executePredecidedAgentActions } from './unified-agent-predecided-actions.part';
import { actionSucceeded } from './unified-agent-tool-router.helpers';
import type { executeToolAction } from './unified-agent-tool-router.helpers';
import { recordAgentRuntimeTurn } from './unified-agent-runtime.helpers';

type UnknownRecord = Record<string, unknown>;
type ToolCallExecutor = typeof executeToolAction;

export async function processUnifiedAgentPredecidedActions(params: {
  predecidedActions: PredecidedAction[];
  allowedTools?: string[];
  contactId: string;
  context?: UnknownRecord;
  phone: string;
  workspaceId: string;
  message: string;
  channel: string;
  conversationHistoryLength: number;
  actions: UnifiedAgentActionsService;
  response: UnifiedAgentResponseService;
  openai: OpenAI | null;
  writerModel: string;
  fallbackWriterModel: string;
  agentRuntime?: AgentRuntimeContextService;
  executeToolAction: ToolCallExecutor;
  toolActionDeps: Parameters<ToolCallExecutor>[6];
  logger: StructuredLogger;
}): Promise<{
  actions: ActionEntry[];
  response?: string;
  intent: string;
  confidence: number;
}> {
  const {
    allowedTools,
    contactId,
    context,
    phone,
    workspaceId,
    message,
    channel,
    conversationHistoryLength,
    actions,
    response,
    openai,
    writerModel,
    fallbackWriterModel,
    agentRuntime,
    executeToolAction: execTool,
    toolActionDeps,
    logger,
  } = params;

  const actionsList = await executePredecidedAgentActions({
    ...(allowedTools !== undefined ? { allowedTools } : {}),
    contactId,
    ...(context !== undefined ? { context } : {}),
    executeTool: (
      wsId: string,
      ctId: string,
      ph: string,
      tool: string,
      args: ToolArgs,
      ctx?: UnknownRecord,
    ) => execTool(wsId, ctId, ph, tool, args, ctx, toolActionDeps, logger),
    logAutopilotEvent: actions.logAutopilotEvent.bind(actions),
    phone,
    predecidedActions: params.predecidedActions,
    workspaceId,
  });

  const intent = response.extractIntent(actionsList, message);
  const draftedReply = await response.composeWriterReply(
    openai,
    writerModel,
    fallbackWriterModel,
    {
      workspaceId,
      customerMessage: message,
      assistantDraft: buildPredecidedActionDraft(actionsList),
      actions: actionsList,
      historyTurns: conversationHistoryLength,
    },
  );

  await recordAgentRuntimeTurn({
    agentRuntime,
    workspaceId,
    channel,
    userMessage: message,
    ...(draftedReply !== undefined ? { assistantMessage: draftedReply } : {}),
    contactId,
    intent,
    confidence: actionsList.length > 0 ? 0.85 : 0.55,
    actions: actionsList.map((action) => ({
      toolName: action.tool,
      success: actionSucceeded(action.result),
      result: action.result,
    })),
  });

  return {
    actions: actionsList,
    ...(draftedReply !== undefined ? { response: draftedReply } : {}),
    intent,
    confidence: actionsList.length > 0 ? 0.85 : 0.55,
  };
}

